import { useEffect, useState } from "react";
import { getComments } from "./api";
import CommentRow from "./CommentRow";

function createState(overrides = {}) {
  return {
    comments: [],
    error: null,
    isLoading: false,
    ...overrides,
  };
}

function CommentFeed({ slug }) {
  const [state, setState] = useState(() => createState({ isLoading: true }));

  useEffect(() => {
    let active = true;
    const controller = new AbortController();

    setState(createState({ isLoading: true }));

    getComments(slug, { signal: controller.signal })
      .then((comments) => {
        if (!active) {
          return;
        }

        setState(createState({ comments }));
      })
      .catch((error) => {
        if (!active || error?.name === "AbortError") {
          return;
        }

        setState(
          createState({
            error: error?.message ?? "Failed to load comments",
          }),
        );
      });

    return () => {
      active = false;
      controller.abort();
    };
  }, [slug]);

  const { comments, error, isLoading } = state;

  if (isLoading) {
    return <p className="loading">Loading comments...</p>;
  }

  if (error) return <p className="error">{error}</p>;
  if (comments.length === 0) return null;

  return (
    <div className="feed">
      {comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentFeed;

const { User, Article, Comment } = require("./models");

const SEED_USERNAME = "u1";
const SEED_ARTICLE_SLUG = "a1";

async function seed() {
  const [user] = await User.findOrCreate({
    where: { username: SEED_USERNAME },
    defaults: { username: SEED_USERNAME },
  });

  const [article] = await Article.findOrCreate({
    where: { slug: SEED_ARTICLE_SLUG },
    defaults: { slug: SEED_ARTICLE_SLUG, userId: user.id },
  });

  const commentCount = await Comment.count({ where: { articleId: article.id } });
  if (commentCount === 0) {
    await Comment.bulkCreate([
      { body: "c1", articleId: article.id, userId: user.id },
      { body: "c2", articleId: article.id, userId: user.id },
    ]);
  }
}

module.exports = { seed };

const fs = require("fs");
const path = require("path");
const { sequelize } = require("../db");
const { createModel } = require("./base");

function loadDefinitions() {
  const definitions = [];
  const modelFiles = fs
    .readdirSync(__dirname)
    .filter(
      (file) =>
        file.endsWith(".js") && file !== "base.js" && file !== "index.js",
    )
    .sort();

  for (const file of modelFiles) {
    definitions.push(require(path.join(__dirname, file)));
  }

  return definitions;
}

function loadModels() {
  const models = {};

  for (const definition of loadDefinitions()) {
    const model = createModel({ sequelize, ...definition });
    models[definition.modelName] = model;
  }

  for (const model of Object.values(models)) {
    if (typeof model.associate === "function") {
      model.associate(models);
    }
  }

  return models;
}

const models = loadModels();

module.exports = { sequelize, ...models };

const ERROR_MESSAGES = {
  not_found: "Comments not found",
  server_error: "Failed to load comments",
};

async function readResponseBody(response) {
  if (response.status === 204) {
    return null;
  }

  const contentType = response.headers.get("content-type") ?? "";

  if (contentType.includes("application/json")) {
    return response.json();
  }

  return response.text();
}

function createApiError(response, body) {
  const code =
    body && typeof body === "object" && "error" in body
      ? String(body.error)
      : null;
  const message =
    (code && ERROR_MESSAGES[code]) ??
    (typeof body === "string" && body.trim() !== "" ? body : null) ??
    `Failed to load comments: ${response.status}`;

  const error = new Error(message);
  error.name = "ApiError";
  error.status = response.status;
  error.body = body;
  return error;
}

function readComments(body) {
  if (body && typeof body === "object" && Array.isArray(body.comments)) {
    return body.comments;
  }

  throw new Error("Invalid comments response");
}

export async function getComments(slug, { signal } = {}) {
  const response = await fetch(
    `/api/articles/${encodeURIComponent(slug)}/comments`,
    { signal },
  );
  const body = await readResponseBody(response);

  if (!response.ok) {
    throw createApiError(response, body);
  }

  return readComments(body);
}

import { useEffect, useState } from "react";
import { getComments } from "./api";
import CommentRow from "./CommentRow";

const STATUS = {
  ERROR: "error",
  LOADING: "loading",
  SUCCESS: "success",
};

function CommentFeed({ slug }) {
  const [state, setState] = useState({
    comments: [],
    error: null,
    status: STATUS.LOADING,
  });

  useEffect(() => {
    let active = true;
    const controller = new AbortController();

    setState({
      comments: [],
      error: null,
      status: STATUS.LOADING,
    });

    getComments(slug, { signal: controller.signal })
      .then((comments) => {
        if (!active) {
          return;
        }

        setState({
          comments,
          error: null,
          status: STATUS.SUCCESS,
        });
      })
      .catch((error) => {
        if (!active || error?.name === "AbortError") {
          return;
        }

        setState({
          comments: [],
          error: error?.message ?? "Failed to load comments",
          status: STATUS.ERROR,
        });
      });

    return () => {
      active = false;
      controller.abort();
    };
  }, [slug]);

  const { comments, error, status } = state;

  if (status === STATUS.LOADING) {
    return <p className="loading">Loading comments...</p>;
  }

  if (status === STATUS.ERROR) return <p className="error">{error}</p>;
  if (comments.length === 0) return null;

  return (
    <div className="feed">
      {comments.map((comment) => (
        <CommentRow key={comment.id} {...comment} />
      ))}
    </div>
  );
}

export default CommentFeed;

